                .andExpect(jsonPath("$.version").value(2));
        // 同 requestId 重放返回首次结果
        mockMvc.perform(post(URL + "/" + id + "/expand").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"req-e1\",\"expectedVersion\":1,\"ratio\":50}"))
