    @Test
    void cancelRolloutAndStateTransitions() throws Exception {
        long id = createRollout("req-c1", "model-a", 10);
        mockMvc.perform(post(URL + "/" + id + "/cancel").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"req-x1\"}"))
